import{_ as e,o as i,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const s="/assets/Install%20Python%20SSL%20Certifications.DlbwErMV.png",f=JSON.parse('{"title":"Install certifi","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/mac-os-installation/install-certifi.md","filePath":"getting-started/mac-os-installation/install-certifi.md"}'),o={name:"getting-started/mac-os-installation/install-certifi.md"};function r(l,t,c,p,h,d){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="install-certifi" tabindex="-1">Install certifi <a class="header-anchor" href="#install-certifi" aria-label="Permalink to &quot;Install certifi&quot;">​</a></h1><p>If you’re encountering, SSLCertVerificationError: [SSL: CERTIFICATE_VERIFY_FAILED] certificate verify failed: unable to get local issuer certificate, is common on macOS when Python is unable to verify SSL certificates due to a missing or inaccessible certificate store. This usually affects the ability to fetch data over HTTPS, such as when attempting to download or use resources like ngrok.</p><p><br> To resolve this issue on macOS, you need to install the certificates for Python. Follow these steps:</p><p>These examples use Python 3.12, the minimum version supported by the current Tradeboard build.</p><p><strong>1. Locate the Correct Path of Python Installation:</strong></p><p>To find the Python 3.12 executable, open Terminal and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>which python3.12</span></span></code></pre></div><p>Locate and Run the Install Certificates Script:</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>Once you have the correct Python 3.12 path, locate the <code>Install Certificates.command</code> helper if your installer supplied it. Homebrew installations commonly use the system certificate store and <code>certifi</code> instead.</p><p>Assuming you installed Python using Homebrew, you might not find an Install Certificates.command. Instead, you can ensure the certificates are installed by manually installing the certifi package and configuring your environment to use it. Here’s how you can do that:</p><ol start="2"><li><strong>Install certifi:</strong></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3.12 -m pip install certifi</span></span></code></pre></div><ol start="3"><li><strong>Set the SSL_CERT_FILE Environment Variable:</strong></li></ol><p>To manually specify the certificate file for Python to use, you can set the SSL_CERT_FILE environment variable to point to the certifi certificate file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export SSL_CERT_FILE=$(python3.12 -m certifi)</span></span></code></pre></div><ol start="4"><li><strong>Retry Running Your Python Code:</strong></li></ol><p>After setting up the certificates through certifi, try running your Python code again. This should resolve any SSL certificate issues.<br></p><p>If a python.org installation includes <code>Install Certificates.command</code>, it is typically under <code>/Applications/Python 3.12/</code>. Run the helper for the same interpreter used by Tradeboard.</p><p>Ensure that you are using the correct paths and commands based on how and where Python is installed on your system.</p>',20)])])}const g=e(o,[["render",r]]);export{f as __pageData,g as default};
